// The brochure's real fonts (Libre Caslon Text + Public Sans), embedded
// directly rather than loaded from Google Fonts at render time. Both are
// real, official Google Fonts under the SIL Open Font License 1.1 --
// sourced via @fontsource (fontsource.org), which repackages exactly the
// same font files Google Fonts itself serves for self-hosting, not a
// substitute or approximation. This removes a genuine reliability risk:
// the brochure previously depended on fonts.googleapis.com being
// reachable at the moment a PDF is generated, which is a real point of
// failure this app has no control over (a slow network, a corporate
// firewall, Google Fonts itself being briefly unavailable) -- self-hosted
// fonts have no such dependency. Only the specific weights the brochure
// actually uses are included (Public Sans 400/500/600/700, Libre Caslon
// Text 400/700 plus 400 italic), not the full family, keeping this to a
// reasonable ~178KB rather than embedding weights nothing here uses.
export const BROCHURE_FONT_FACES = `
@font-face { font-family: 'Public Sans'; font-weight: 400; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,') format('woff2'); }
@font-face { font-family: 'Public Sans'; font-weight: 500; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,') format('woff2'); }
@font-face { font-family: 'Public Sans'; font-weight: 600; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,') format('woff2'); }
@font-face { font-family: 'Public Sans'; font-weight: 700; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,') format('woff2'); }
@font-face { font-family: 'Libre Caslon Text'; font-weight: 400; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,') format('woff2'); }
@font-face { font-family: 'Libre Caslon Text'; font-weight: 700; font-style: normal; font-display: swap; src: url(data:font/woff2;base64,') format('woff2'); }
@font-face { font-family: 'Libre Caslon Text'; font-weight: 400; font-style: italic; font-display: swap; src: url(data:font/woff2;base64,') format('woff2'); }
`;
